export function tx(k, params) {
  const s = SETTINGS_TEXT[I18N.lang]?.[k] || UI_TEXT[k]?.[I18N.lang] || SETTINGS_TEXT["zh-TW"][k] || k;  return params ? s.replace(/\{(\w+)\}/g, (m, n) => params[n] ?? m) : s;  // tx('鍵',{x:值})：佔位值由呼叫端自行跳脫
}
